#!/usr/bin/env Rscript
options(stringsAsFactors=FALSE,warn=1,width=180);a<-commandArgs(trailingOnly=TRUE);if(length(a)!=2L||a[[1]]!="--config")stop("usage")
suppressPackageStartupMessages({library(scworkbench);library(scwbLatent);library(Matrix);library(RANN);library(yaml);library(jsonlite);library(digest)})
rcfg<-function(p){x<-yaml::read_yaml(p);b<-x$base_config;x$base_config<-NULL;if(is.null(b))return(x);utils::modifyList(rcfg(normalizePath(file.path(dirname(p),b))),x,keep.null=TRUE)}
sha<-function(p)digest::digest(p,algo="sha256",file=TRUE);wtsv<-function(x,p)write.table(x,p,sep="\t",quote=TRUE,row.names=FALSE,na="NA");wjson<-function(x,p)jsonlite::write_json(x,p,pretty=TRUE,auto_unbox=TRUE,digits=NA,null="null",na="null");logx<-function(...){cat(format(Sys.time(),tz="UTC",usetz=TRUE),...,"\n");flush.console()};asm<-function(x){if(is.data.frame(x)){id<-x$cell_id;x<-as.matrix(x[,setdiff(names(x),"cell_id"),drop=FALSE]);rownames(x)<-id}else x<-as.matrix(x);x};ent<-function(g,w){p<-tapply(w,g,sum);p<-p/sum(p);if(length(p)<=1)0 else -sum(p*log(p))/log(length(p))};corx<-function(x,y)if(sd(x)==0||sd(y)==0)NA_real_ else suppressWarnings(cor(x,y,method="spearman"));pid<-function(p,o){z<-p$promoted$status=="ok"&p$promoted$output==o;as.character(p$promoted$artifact_id[z][[1]])}
cfgp<-normalizePath(a[[2]],mustWork=TRUE);cfg<-rcfg(cfgp);root<-cfg$storage$results_root;dirs<-setNames(file.path(root,c("01_tables","02_figures","03_reports","04_logs","05_objects","06_manifests")),c("tables","figures","reports","logs","objects","manifests"));sink(file.path(dirs[["logs"]],"02_project_immgen.log"),split=TRUE);on.exit(try(sink(),silent=TRUE),add=TRUE)
lm<-system.file("scworkbench","operation-pack.json",package="scwbLatent");stopifnot(sha(lm)==cfg$runtime$scwbLatent$manifest_sha256);wb_operation_pack_activate(lm,lib.loc=.libPaths())
fp<-file.path(dirs[["manifests"]],"02_pre_external_freeze_receipt.json");fr<-jsonlite::read_json(fp,simplifyVector=TRUE);rp<-file.path(dirs[["tables"]],"04_frozen_hvp_model_registry.tsv");ap<-file.path(dirs[["tables"]],"03_hvp20k_source_order_axes.tsv.gz");stopifnot(fr$status=="two_hvp_models_frozen_external_unread",sha(rp)==fr$model_registry$sha256,sha(ap)==fr$feature_axes$sha256)
reg<-read.delim(rp,check.names=FALSE,quote="\"");axes<-read.delim(gzfile(ap),check.names=FALSE,quote="\"");cands<-unlist(cfg$model$candidates,use.names=FALSE);libs<-read.delim(cfg$external_evaluation$library_manifest$path,check.names=FALSE,quote="");stopifnot(nrow(libs)==28L,sha(file.path(cfg$external_evaluation$query_bundle$path,"manifest.json"))==cfg$external_evaluation$query_bundle$manifest_sha256,sha(cfg$external_evaluation$library_manifest$path)==cfg$external_evaluation$library_manifest$sha256)
slots<-sprintf("external_query_%03d",seq_len(nrow(libs)));slotmap<-data.frame(slot_id=slots,gsm=libs$gsm,population=libs$population,lineage=libs$lineage,stringsAsFactors=FALSE);wtsv(slotmap,file.path(dirs[["tables"]],"05_external_query_slot_map.tsv"));b<-wb_open_bundle(cfg$storage$frozen_bundle,validate=FALSE,read_only=FALSE);on.exit(try(wb_close_bundle(b),silent=TRUE),add=TRUE);allcells<-as.character(wb_cells(b,"all"));refs<-head(allcells,length(allcells)-length(slots));before<-setNames(vapply(seq_len(nrow(reg)),function(i)sha(reg$model_payload_path[i]),character(1)),reg$candidate);stopifnot(all(before==reg$model_payload_sha256));logx("Frozen payloads validated before external counts")
q<-wb_open_bundle(cfg$external_evaluation$query_bundle$path,validate=FALSE,read_only=TRUE);qaxis<-as.character(wb_feature_ids(q,cfg$external_evaluation$query_bundle$matrix));full<-wb_slice(q,cfg$external_evaluation$query_bundle$matrix,features=qaxis,cells=libs$gsm);colnames(full)<-slots;common<-colSums(full);wb_close_bundle(q)
refmeta<-wb_meta(b,cells=refs,cols=list(wb_ref_metadata_field("core:cell_id"),cfg$inputs$cluster_field,cfg$inputs$sample_field,cfg$inputs$depth_field,"l4_weight","native_l4"));maps<-neis<-mets<-list()
for(candidate in cands){axis<-axes$feature_id[axes$candidate==candidate];x<-full[axis,,drop=FALSE];qid<-paste0(candidate,"_immgen_counts");if(!(qid%in%wb_matrices(b)$matrix_id))wb_attach_matrix(b,qid,x,layer="counts",feature_type="peak",cell_ids=slots,description=candidate,source="frozen ImmGen evaluation",created_by="step14 post-freeze");row<-reg[reg$candidate==candidate,,drop=FALSE];space<-paste0("frozen_",candidate,"_immgen_queries");arts<-wb_art_list(b);take<-arts$source_op=="scwblatent::peakvi_project"&arts$input_space_id%in%space&arts$type=="obs_table"&arts$lifecycle_state=="current";if(sum(take)==1L){paid<-as.character(arts$artifact_id[take][[1]])}else{s<-wb_session_create(b,cfg$storage$sessions,paste0(cfg$run_identity,"_",candidate,"_project"));r<-wb_session_run_op(s,b,"scwblatent::peakvi_project",inputs=list(model=wb_ref_artifact(as.character(row$model_artifact_id),"model"),query_matrix=qid,space_id_out=space,chunk_size=as.integer(cfg$peakvi$chunk_size),batch_key=NULL,use_gpu=FALSE,pickle_execution_trust=cfg$peakvi$pickle_execution_trust,cell_set="all",min_cells=1L),notes=paste("post-freeze",candidate));stopifnot(r$run$outputs$projection_summary$table$transformation[[1]]=="transfer_without_refit");r$session<-wb_session_resume(b,r$session$durable$workspace);p<-wb_session_promote_current(b,r$session,outputs="projection_summary",name_prefix=paste0("frozen_",candidate,"_immgen"),description=candidate,created_by="step14 post-freeze",fail_fast=TRUE);paid<-pid(p,"projection_summary");p$session<-wb_session_discard(p$session)};rl<-asm(wb_space(b,as.character(row$reference_space_id),cells=refs));ql<-asm(wb_space(b,space,cells=slots));k<-cfg$external_evaluation$neighbor_k;nn<-RANN::nn2(rl,ql,k=k);rmed<-median(RANN::nn2(rl,rl,k=2)$nn.dists[,2]);cl<-as.character(refmeta[[cfg$inputs$cluster_field]]);sa<-as.character(refmeta[[cfg$inputs$sample_field]]);lw<-as.numeric(refmeta$l4_weight);pt<-as.numeric(refmeta$native_l4);sat<-colSums(x!=0)/nrow(x);ml<-nl<-vector("list",length(slots));for(i in seq_along(slots)){ix<-nn$nn.idx[i,];d<-nn$nn.dists[i,];w<-1/pmax(d,1e-8);cw<-tapply(w,cl[ix],sum);pred<-names(cw)[order(-cw,names(cw),method="radix")][[1]];li<-which(lw[ix]>=cfg$external_evaluation$l4_weight_positive_threshold&is.finite(pt[ix]));ppt<-if(length(li)>=cfg$external_evaluation$minimum_l4_neighbors)weighted.mean(pt[ix[li]],w[li])else NA_real_;ml[[i]]<-data.frame(candidate=candidate,slot_id=slots[i],gsm=libs$gsm[i],population=libs$population[i],lineage=libs$lineage[i],common_total_peak_counts=common[i],candidate_peak_counts=colSums(x)[i],peak_saturation=sat[i],predicted_bdev_cluster=pred,nearest_reference_distance=min(d),nearest_distance_over_reference_median=min(d)/rmed,neighbor_sample_entropy=ent(sa[ix],w),neighbor_l4_weight=weighted.mean(lw[ix],w),provisional_native_l4=ppt,trajectory_output_status=cfg$external_evaluation$trajectory_output_status,projection_artifact_id=paid,stringsAsFactors=FALSE);nl[[i]]<-data.frame(candidate=candidate,slot_id=slots[i],gsm=libs$gsm[i],rank=seq_len(k),reference_cell_id=refs[ix],distance=d,reference_cluster=cl[ix],reference_sample=sa[ix],reference_l4_weight=lw[ix],stringsAsFactors=FALSE)};m<-do.call(rbind,ml);n<-do.call(rbind,nl);maps[[candidate]]<-m;neis[[candidate]]<-n;qd<-as.matrix(dist(ql));pairs<-which(upper.tri(qd),arr.ind=TRUE);same<-libs$population[pairs[,1]]==libs$population[pairs[,2]];rep<-mean(m$predicted_bdev_cluster[pairs[same,1]]==m$predicted_bdev_cluster[pairs[same,2]]);dc<-apply(ql,2,corx,y=log1p(common));sc<-apply(ql,2,corx,y=sat);mets[[candidate]]<-data.frame(candidate=candidate,features=nrow(x),query_libraries=nrow(ql),within_population_to_between_population_latent_distance_ratio=median(qd[pairs[same,,drop=FALSE]])/median(qd[pairs[!same,,drop=FALSE]]),replicate_predicted_cluster_agreement=rep,unique_reference_neighbors=length(unique(n$reference_cell_id)),maximum_reference_hub_fraction=max(table(n$reference_cell_id))/nrow(n),median_nearest_distance_over_reference_median=median(m$nearest_distance_over_reference_median),median_neighbor_sample_entropy=median(m$neighbor_sample_entropy),maximum_absolute_depth_latent_spearman=max(abs(dc),na.rm=TRUE),maximum_absolute_saturation_latent_spearman=max(abs(sc),na.rm=TRUE),median_neighbor_l4_weight=median(m$neighbor_l4_weight),finite_provisional_l4_libraries=sum(is.finite(m$provisional_native_l4)),model_payload_sha256_before=before[[candidate]],stringsAsFactors=FALSE);logx("Projected",candidate)}
maps<-do.call(rbind,maps);neis<-do.call(rbind,neis);mets<-do.call(rbind,mets);after<-setNames(vapply(seq_len(nrow(reg)),function(i)sha(reg$model_payload_path[i]),character(1)),reg$candidate);stopifnot(all(after==before));mets$model_payload_sha256_after=after[mets$candidate];wtsv(maps,file.path(dirs[["tables"]],"06_hvp_immgen_mappings.tsv"));con<-gzfile(file.path(dirs[["tables"]],"07_hvp_immgen_neighbors.tsv.gz"),"wt");write.table(neis,con,sep="\t",quote=TRUE,row.names=FALSE,na="NA");close(con);wtsv(mets,file.path(dirs[["tables"]],"08_hvp_external_metrics.tsv"));wb_finalize_recipient_bundle(b);wb_close_bundle(b);b<-NULL
wjson(list(schema_version="bdev.hvp20k_external.v1",status="complete_no_automatic_default_change",run_identity=cfg$run_identity,candidates=cands,projection_without_refit=TRUE,models_unchanged=TRUE,current_default_changed=FALSE),file.path(dirs[["reports"]],"01_hvp_external_summary.json"));wjson(list(schema_version="bdev.hvp20k_external_receipt.v1",status="complete",config_sha256=sha(cfgp),freeze_receipt_sha256=sha(fp),model_payload_before=as.list(before),model_payload_after=as.list(after),current_default_changed=FALSE),file.path(dirs[["manifests"]],"03_external_execution_receipt.json"));logx("HVP external comparison complete")
